using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Configuration -----------------------------------------------------------

var openAiModel = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

// --- Tool state: notebook ----------------------------------------------------

var notebook = new List<(string Title, string Content)>();

// --- Tool definitions --------------------------------------------------------

var searchWebTool = AIFunctionFactory.Create(SearchWebAsync,
    name: "search_web",
    description: "Search the web for a query and return a list of result snippets.");

var saveNoteTool = AIFunctionFactory.Create(SaveNote,
    name: "save_note",
    description: "Save a research note with a short title and longer content.");

var readNotesTool = AIFunctionFactory.Create(ReadNotes,
    name: "read_notes",
    description: "Read all research notes saved so far.");

// --- Build the chat pipeline -------------------------------------------------

IChatClient client = new ChatClientBuilder(
        new OpenAIClient(apiKey).GetChatClient(openAiModel).AsIChatClient())
    .UseFunctionInvocation()
    .Build();

var systemPrompt = """
    You are a research agent. Given a topic, you:
    1. Search the web multiple times to gather diverse information.
    2. Save important findings as notes using the save_note tool.
    3. After you have gathered enough information, read your notes and
       produce a well-structured summary with references.
    Always search at least twice with different queries before summarizing.
    """;

// --- Agent loop --------------------------------------------------------------

Console.WriteLine("╔══════════════════════════════════════════╗");
Console.WriteLine("║        AI Research Agent                 ║");
Console.WriteLine("╚══════════════════════════════════════════╝");
Console.Write("\nEnter a research topic (or 'quit' to exit): ");

while (Console.ReadLine() is { } topic && !topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
{
    if (string.IsNullOrWhiteSpace(topic))
    {
        Console.Write("\nEnter a research topic (or 'quit' to exit): ");
        continue;
    }

    notebook.Clear();
    Console.WriteLine($"\n🔍 Researching: {topic}\n");

    var messages = new List<ChatMessage>
    {
        new(ChatRole.System, systemPrompt),
        new(ChatRole.User, $"Research the following topic and provide a comprehensive summary: {topic}"),
    };

    var options = new ChatOptions
    {
        Tools = [searchWebTool, saveNoteTool, readNotesTool],
    };

    try
    {
        var response = await client.GetResponseAsync(messages, options);
        Console.WriteLine("\n────────────────────────────────────────────");
        Console.WriteLine(response.Text);
        Console.WriteLine("────────────────────────────────────────────");

        if (notebook.Count > 0)
        {
            Console.WriteLine($"\n📒 {notebook.Count} note(s) saved during research.");
        }
    }
    catch (Exception ex)
    {
        Console.WriteLine($"\n❌ Error: {ex.Message}");
    }

    Console.Write("\nEnter a research topic (or 'quit' to exit): ");
}

Console.WriteLine("Goodbye!");

// =============================================================================
// Tool implementations
// =============================================================================

[Description("Search the web for a query and return a list of result snippets.")]
async Task<string> SearchWebAsync(
    [Description("The search query")] string query,
    [Description("Maximum number of results to return")] int maxResults = 5)
{
    Console.WriteLine($"  🌐 Searching: \"{query}\"");

    try
    {
        using var http = new HttpClient();
        // Use DuckDuckGo Instant Answer API (no key required)
        var url = $"https://api.duckduckgo.com/?q={Uri.EscapeDataString(query)}&format=json&no_html=1";
        var ddg = await http.GetFromJsonAsync<JsonElement>(url);

        var results = new List<string>();

        // Abstract / main answer
        var abstractText = ddg.GetProperty("AbstractText").GetString();
        var abstractSource = ddg.GetProperty("AbstractSource").GetString();
        var abstractUrl = ddg.GetProperty("AbstractURL").GetString();
        if (!string.IsNullOrWhiteSpace(abstractText))
        {
            results.Add($"[{abstractSource}] {abstractText}\n  URL: {abstractUrl}");
        }

        // Related topics
        if (ddg.TryGetProperty("RelatedTopics", out var topics) && topics.ValueKind == JsonValueKind.Array)
        {
            foreach (var item in topics.EnumerateArray())
            {
                if (results.Count >= maxResults) break;
                var text = item.TryGetProperty("Text", out var t) ? t.GetString() : null;
                var link = item.TryGetProperty("FirstURL", out var u) ? u.GetString() : null;
                if (!string.IsNullOrWhiteSpace(text))
                {
                    results.Add($"{text}\n  URL: {link}");
                }
            }
        }

        if (results.Count == 0)
        {
            // Fall back to the "Answer" field
            var answer = ddg.GetProperty("Answer").GetString();
            if (!string.IsNullOrWhiteSpace(answer))
                results.Add(answer);
        }

        return results.Count > 0
            ? string.Join("\n\n---\n\n", results)
            : "No results found. Try rephrasing the query.";
    }
    catch (Exception ex)
    {
        return $"Search failed: {ex.Message}. Try a different query.";
    }
}

[Description("Save a research note with a short title and longer content.")]
string SaveNote(
    [Description("Short title for the note")] string title,
    [Description("The content of the note")] string content)
{
    notebook.Add((title, content));
    Console.WriteLine($"  📝 Note saved: \"{title}\"");
    return $"Note '{title}' saved (total notes: {notebook.Count}).";
}

[Description("Read all research notes saved so far.")]
string ReadNotes()
{
    if (notebook.Count == 0)
        return "No notes saved yet.";

    Console.WriteLine($"  📖 Reading {notebook.Count} note(s)");
    return string.Join("\n\n", notebook.Select((n, i) =>
        $"Note {i + 1}: {n.Title}\n{n.Content}"));
}

